"""deploy/vercel is generated by scripts/make_vercel_bundle.py: it must always match the real sources."""
import importlib.util
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
COMMITTED = ROOT / "deploy" / "vercel"


def load_generator():
    spec = importlib.util.spec_from_file_location("make_vercel_bundle", ROOT / "scripts" / "make_vercel_bundle.py")
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    return module


def files_of(folder: Path) -> dict[str, bytes]:
    # line endings are ignored: a Windows checkout may turn LF into CRLF
    return {p.relative_to(folder).as_posix(): p.read_bytes().replace(b"\r\n", b"\n")
            for p in folder.rglob("*") if p.is_file() and "__pycache__" not in p.parts}


def test_the_committed_bundle_matches_the_sources(tmp_path):
    load_generator().build(tmp_path)
    fresh, committed = files_of(tmp_path), files_of(COMMITTED)
    assert set(fresh) == set(committed), "run: python scripts/make_vercel_bundle.py"
    stale = [name for name in fresh if fresh[name] != committed[name]]
    assert not stale, f"out of date, run: python scripts/make_vercel_bundle.py ({stale})"


def test_the_bundle_installs_no_tensorflow():
    pins = (COMMITTED / "requirements.txt").read_text().lower()
    for heavy in ("tensorflow", "keras", "numpy", "gunicorn"):
        assert heavy not in pins
    for needed in ("flask==", "sqlalchemy==", "psycopg[binary]==", "pillow==", "requests=="):
        assert needed in pins


def test_the_entry_point_and_static_files_are_in_place():
    assert "app = create_app()" in (COMMITTED / "app.py").read_text()
    assert (COMMITTED / "public" / "static" / "style.css").is_file()
    assert (COMMITTED / "vercel.json").is_file() and (COMMITTED / ".python-version").read_text().strip() == "3.12"
